#!/usr/bin/env python3
from pathlib import Path
import sys
from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib.units import mm
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,PageBreak,Table,TableStyle,Image,KeepTogether
OUT=Path(sys.argv[1]) if len(sys.argv)>1 else Path('GUIA_ESTADISTICAS_v3.pdf');CAP=Path(sys.argv[2]) if len(sys.argv)>2 else None
REG='/usr/share/fonts/liberation/LiberationSans-Regular.ttf';BOLD='/usr/share/fonts/liberation/LiberationSans-Bold.ttf'
if not Path(REG).exists(): REG='/usr/share/fonts/dejavu-sans-fonts/DejaVuSans.ttf';BOLD='/usr/share/fonts/dejavu-sans-fonts/DejaVuSans-Bold.ttf'
pdfmetrics.registerFont(TTFont('UI',REG));pdfmetrics.registerFont(TTFont('UIB',BOLD))
INK=colors.HexColor('#17191F');MUTED=colors.HexColor('#626975');RED=colors.HexColor('#C8393B');GREEN=colors.HexColor('#187447');BLUE=colors.HexColor('#266A9B');PALE=colors.HexColor('#F0F2F5');LINE=colors.HexColor('#DFE2E8')
S=getSampleStyleSheet();S.add(ParagraphStyle(name='Cover',fontName='UIB',fontSize=32,leading=35,textColor=INK,spaceAfter=8));S.add(ParagraphStyle(name='H1x',fontName='UIB',fontSize=22,leading=26,textColor=INK,spaceAfter=10));S.add(ParagraphStyle(name='H2x',fontName='UIB',fontSize=13,leading=17,textColor=INK,spaceBefore=8,spaceAfter=5));S.add(ParagraphStyle(name='Bodyx',fontName='UI',fontSize=9.5,leading=14,textColor=INK,spaceAfter=7));S.add(ParagraphStyle(name='Smallx',fontName='UI',fontSize=7.8,leading=10.5,textColor=MUTED,spaceAfter=5));S.add(ParagraphStyle(name='Step',fontName='UIB',fontSize=10.2,leading=14,textColor=INK,leftIndent=8,borderColor=GREEN,borderWidth=1,borderPadding=7,spaceAfter=7));S.add(ParagraphStyle(name='Note',fontName='UI',fontSize=8.8,leading=13,textColor=INK,backColor=PALE,borderColor=LINE,borderWidth=.6,borderPadding=8,spaceAfter=8));S.add(ParagraphStyle(name='CodeX',fontName='Courier',fontSize=8,leading=11,textColor=INK,backColor=PALE,borderPadding=7,spaceAfter=7))
def P(t,st='Bodyx'): return Paragraph(t,S[st])
def bullets(items): return [P('• '+x) for x in items]
def steps(items): return [P(f'{i} · {x}','Step') for i,x in enumerate(items,1)]
def pic(name,w=168*mm,h=100*mm):
 if not CAP or not (CAP/name).exists(): return Spacer(1,1)
 im=Image(str(CAP/name));im._restrictSize(w,h);return im
def footer(c,d):
 c.saveState();c.setFont('UI',7);c.setFillColor(MUTED);c.drawString(18*mm,10*mm,'ESTADÍSTICAS v3 · Buen Consejo 26/27');c.drawRightString(192*mm,10*mm,str(d.page));c.restoreState()
def new(title,subtitle=None):
 a=[P(title,'H1x')]
 if subtitle:a.append(P(subtitle,'Smallx'))
 return a
def table(rows,widths): return Table(rows,colWidths=widths,repeatRows=1,style=TableStyle([('FONT',(0,0),(-1,-1),'UI',8),('FONT',(0,0),(-1,0),'UIB',8),('BACKGROUND',(0,0),(-1,0),INK),('TEXTCOLOR',(0,0),(-1,0),colors.white),('GRID',(0,0),(-1,-1),.4,LINE),('VALIGN',(0,0),(-1,-1),'TOP'),('PADDING',(0,0),(-1,-1),5)]))
doc=SimpleDocTemplate(str(OUT),pagesize=A4,rightMargin=18*mm,leftMargin=18*mm,topMargin=18*mm,bottomMargin=18*mm,title='Guía Estadísticas v3',author='Microsoft Copilot');story=[]
story += [Spacer(1,20*mm),P('GUÍA CLIC A CLIC · DESDE CERO','Smallx'),P('Estadísticas v3','Cover'),P('Buen Consejo · temporada 26/27','H1x'),P('Publicar, conectar, instalar, usar, configurar tu Gem de Gemini y tu proyecto de Claude, y actualizar la app sin saber programar.'),Spacer(1,4*mm),pic('01_PC_CLARO_EQUIPO.png',170*mm,82*mm),P('<b>Importante:</b> esta guía es para v3. No uses una guía de v1 o v2.','Note'),P('Noviembre de 2026','Smallx'),PageBreak()]
story += new('Antes de empezar')+bullets(['Necesitas una cuenta de GitHub y una de Cloudflare.','Para el asistente de cambios, usa una cuenta de Gemini con Gems y/o una cuenta de Claude con Projects. Si tu plan no muestra esas opciones, usa el otro servicio.','Trabaja desde un ordenador para publicar. Después usarás la app en el móvil.','No borres la carpeta <b>assets</b> que ya está en tu repositorio: conserva <b>jszip.min.js</b> y los iconos.'])+[P('Qué contiene el ZIP','H2x'),table([['Carpeta','Qué hacer'],['1_CODIGO_GITHUB','Copiar a la raíz del repositorio y reemplazar.'],['2_PARA_TI','Guardar en tu ordenador; no subir a GitHub.']], [55*mm,115*mm]),P('Orden recomendado','H2x')]+steps(['Publica el código.','Crea Cloudflare D1 y Worker.','Genera tus enlaces.','Instala la app.','Importa los Excel.','Configura Gemini y Claude.'])+[PageBreak()]
story += new('1. Guardar una copia y pasar a v3')+steps(['En el dispositivo donde usabas v2, abre la dirección pública de tu app y añade <b>/actualizar.html</b>.','En “Copia de seguridad”, pulsa <b>Descargar datos locales</b>. Guarda el JSON.','Descomprime el ZIP de v3 en el ordenador.','No desinstales la app y no borres datos del navegador. v3 conserva la clave <b>estadisticas_shared_v2</b>.','Después de publicar v3, abre la app y recarga. Comprueba Partidos, Jugadoras y mapas.'])+[P('Si nunca publicaste v2, no pasa nada: sigue directamente con el capítulo 2.','Note'),PageBreak()]
story += new('2. Crear o abrir el repositorio en GitHub')+steps(['Entra en <b>github.com</b> e inicia sesión.','Pulsa el botón <b>+</b> de arriba y <b>New repository</b>.','Nombre: <b>estadisticas</b>. Elige Private o Public según permita tu Pages.','Marca <b>Add a README</b> si GitHub lo exige y pulsa <b>Create repository</b>.','En GitHub Desktop: File → Clone repository → elige <b>estadisticas</b> → Clone.','Abre la carpeta local del repositorio.'])+[P('Si ya existe el repositorio, solo ábrelo en GitHub Desktop y pulsa <b>Fetch origin</b> antes de copiar.','Note'),PageBreak()]
story += new('3. Copiar v3 y publicar')+steps(['Abre la carpeta <b>1_CODIGO_GITHUB</b> del ZIP.','Selecciona todo lo que hay dentro, incluida <b>.github</b>.','Cópialo a la raíz de tu repositorio <b>estadisticas</b> y acepta <b>Reemplazar</b>.','No copies <b>2_PARA_TI</b>.','Comprueba que la carpeta <b>assets</b> antigua sigue dentro del repositorio.','En GitHub Desktop escribe el resumen <b>Estadísticas v3</b>.','Pulsa <b>Commit to main</b> y luego <b>Push origin</b>.','En GitHub: Settings → Pages → Source: Deploy from a branch → main / root → Save.','Espera al enlace de Pages y ábrelo.'])+[P('Prueba rápida: arriba debe verse “Estadísticas” y en la barra lateral o pie debe indicar v3.','Note'),PageBreak()]
story += new('4. Crear la base D1 en Cloudflare')+steps(['Entra en <b>dash.cloudflare.com</b>.','Abre <b>Workers & Pages</b>.','Busca <b>D1 SQL Database</b> o <b>Storage & Databases → D1</b>.','Pulsa <b>Create database</b>.','Nombre: <b>estadisticas</b>. Pulsa Create.','No necesitas crear tablas a mano: el Worker las crea al configurarse.'])+[P('Deja esta pestaña abierta. En el paso siguiente la enlazarás al Worker con el nombre exacto <b>DB</b>.','Note'),PageBreak()]
story += new('5. Crear el Worker')+steps(['En Cloudflare: Workers & Pages → Create → Worker.','Nombre: <b>estadisticas</b>. Pulsa Deploy.','Pulsa <b>Edit code</b>.','Abre <b>worker.js</b> de 1_CODIGO_GITHUB con el Bloc de notas.','Selecciona todo, copia y reemplaza todo el código del editor de Cloudflare.','Pulsa <b>Deploy</b>.','Ve a Settings → Bindings → Add → D1 database.','Variable name: <b>DB</b>. Database: <b>estadisticas</b>. Guarda.','Ve a Settings → Variables and Secrets → Add.','Tipo Secret; nombre <b>SETUP_SECRET</b>; valor: una frase larga que solo tú conozcas. Guarda y vuelve a desplegar.','Abre la URL del Worker seguida de <b>/health</b>. Debe mostrar <b>{"ok":true,"version":"w3"}</b>.'])+[P('Nunca subas SETUP_SECRET a GitHub ni lo envíes al equipo.','Note'),PageBreak()]
story += new('6. Crear los enlaces de acceso')+steps(['Abre tu GitHub Pages y añade <b>/configurar.html</b>.','Pega la URL completa del Worker, sin barra final.','Pega SETUP_SECRET.','Pega la URL pública de la app.','Pulsa <b>Crear enlaces</b>.','Guarda tu enlace de administrador en un gestor de contraseñas.','Envía enlace de edición solo a quien vaya a importar o apuntar.','Envía enlace de lectura a quien solo consulte.'])+[P('Cada persona debe abrir su propio enlace. El token queda guardado en ese navegador.','Note'),PageBreak()]
story += new('7. Instalar y comprobar el tema')+steps(['Android: abre el enlace en Chrome → pulsa ⇩ Instalar. Si no sale: menú ⋮ → Instalar aplicación.','iPhone: abre en Safari → Compartir → Añadir a pantalla de inicio.','Abre la app instalada.','Pulsa Tema y comprueba que el fondo oscuro es gris casi negro y que no quedan franjas blancas arriba o abajo.','Vuelve al tema que prefieras.'])+[pic('06_MOVIL_390x844_OSCURO_EQUIPO.png',78*mm,136*mm),P('Si se mantiene una versión antigua: cierra la app instalada, abre la URL en el navegador, recarga y vuelve a abrir.','Note'),PageBreak()]
story += new('8. Importar plantilla y actas')+steps(['Jugadoras → <b>Actualizar plantilla</b> → elige el Excel Jugadores-Equipo.','Equipo o Partidos → <b>Importar acta</b>. Puedes seleccionar varios Excel a la vez.','Revisa la fecha propuesta para cada partido. El Excel no contiene la fecha real.','Pulsa <b>Guardar actas</b>.','Abre un partido y cambia entre <b>Buen Consejo</b> y <b>Rival</b>.','Desliza la tabla horizontalmente. Toca cualquier cabecera una vez para ordenar y otra para invertir.'])+[pic('03_PC_CLARO_PARTIDO.png',168*mm,92*mm),P('Las dos filas “X · NOMBRE” de Olímpico deben aparecer separadas.','Note'),PageBreak()]
story += new('9. Usar Directo')+steps(['Antes del partido: Directo → escribe rival y fecha.','Marca o desmarca convocadas. Esta pantalla sí permite bajar con el dedo.','Pulsa <b>Empezar partido</b>.','Elige cuarto 1º, 2º, 3º o 4º.','Toca Robo, Pérdida o Rebote ofensivo y elige jugadora.','Rebote rival se registra sin jugadora.','Si te equivocas, pulsa Deshacer.','Pulsa Finalizar y guardar. La app intenta unirlo al acta por rival y fecha.'])+[pic('08_MOVIL_360x640_OSCURO_DIRECTO_CURSO.png',78*mm,138*mm),P('En curso, los cuatro botones, cuartos, Deshacer y Finalizar deben caber sin desplazamiento incluso en 360×640.','Note'),PageBreak()]
story += new('10. Añadir y revisar mapas')+steps(['Partidos → <b>Añadir mapa</b>.','Selecciona el partido.','Pulsa <b>Copiar prompt para mi IA</b>.','Abre tu Gem o proyecto de Claude, adjunta la captura de Afición FBM y pega el prompt.','Copia solo el JSON devuelto.','En la app: Pegar respuesta JSON → pega → Colocar las dos listas.','Comprueba cabecera, equipo, lado y color. Si no coinciden, usa <b>Intercambiar equipos</b>.','Toca para añadir, arrastra para mover y selecciona para borrar.','Pulsa <b>Guardar ambos mapas</b>.'])+[P('Zonas exactas: Pintura, Media distancia, Triple de esquina y Triple. Las barras muestran reparto de canastas, no acierto.','Note'),PageBreak()]
story += new('11. Leer Equipo, Jugadoras y Partidos')+bullets(['<b>Equipo:</b> Estadísticas avanzadas en Ataque y Defensa. Toca una métrica para ver definición y partidos.','<b>Mapas:</b> alterna ataque, defensa y juntos; filtra rival y casa/fuera.','<b>Jugadoras:</b> totales, medias, por 40, valoración, +/-, cuotas, Directo y evolución.','<b>Partido a partido:</b> toca un partido de una jugadora para abrir inmediatamente el acta.','<b>Acta:</b> selector de equipo, 26 columnas, nombre fijo y ordenación en todas las cabeceras.'])+[pic('10_MOVIL_412x915_OSCURO_JUGADORA.png',78*mm,138*mm),PageBreak()]
story += new('12. Crear el Gem de Gemini','Configuración inicial, clic a clic')+steps(['Entra en <b>gemini.google.com</b> con tu cuenta.','En el menú lateral pulsa <b>Gems</b> o <b>Explorar Gems</b>.','Pulsa <b>Nuevo Gem</b> o <b>Crear Gem</b>.','Nombre: <b>Estadísticas Dev v3</b>.','Abre <b>INSTRUCCIONES_GEM_GEMINI_v3.txt</b> de 2_PARA_TI. Selecciona todo y pégalo en Instrucciones.','En Conocimiento pulsa <b>+</b> o <b>Subir archivos</b>.','Sube exactamente: <b>AGENTS.md</b>, <b>CONTEXTO_ESTADISTICAS.md</b>, <b>MAPA_DEL_CODIGO.md</b> y <b>PROMPT_MAPA_TIRO.md</b>.','Pulsa Guardar.','Haz una prueba: “Dime la versión y la clave local que no debes cambiar”. Debe responder v3 y estadisticas_shared_v2.'])+[P('Si no aparece Gems, tu cuenta o región puede no incluirlo. Usa el proyecto de Claude o un chat normal adjuntando las instrucciones y el archivo enfocado.','Note'),PageBreak()]
story += new('13. Crear el proyecto de Claude','Configuración inicial, clic a clic')+steps(['Entra en <b>claude.ai</b> e inicia sesión.','Pulsa <b>Projects</b>.','Pulsa <b>Create project</b>.','Nombre: <b>Estadísticas Dev v3</b>.','Abre Project instructions / Set instructions.','Abre <b>INSTRUCCIONES_PROYECTO_CLAUDE_v3.txt</b>, copia todo y pégalo. Guarda.','En Project knowledge pulsa <b>Add content</b> o <b>+</b>.','Sube: <b>AGENTS.md</b>, <b>CONTEXTO_ESTADISTICAS.md</b>, <b>MAPA_DEL_CODIGO.md</b> y <b>PROMPT_MAPA_TIRO.md</b>.','Haz la misma prueba de versión y clave local.'])+[P('Si Projects no aparece, puede depender del plan. Usa Gemini o un chat normal con los mismos cinco archivos.','Note'),PageBreak()]
story += new('14. Pedir un cambio gastando poco límite')+steps(['Abre <b>actualizar.html</b> desde tu GitHub Pages.','Escribe una frase corta del cambio.','Elige un solo archivo, por ejemplo app.js o styles.css.','Pulsa <b>Descargar paquete para la IA</b>.','Abre un <b>chat nuevo</b> en el Gem o proyecto. Un chat nuevo por cambio.','Adjunta el TXT enfocado y escribe la petición concreta.','Pide siempre: “Devuelve el archivo completo, sin omitir partes”.','No adjuntes toda la app salvo que la IA explique por qué necesita otro archivo.'])+[P('Usar un chat nuevo evita arrastrar contexto y reduce el consumo del límite.','Note'),PageBreak()]
story += new('15. Aplicar la respuesta de la IA')+steps(['Copia la respuesta completa.','En actualizar.html, pégala en <b>Respuesta completa de la IA</b>.','Pulsa <b>Aplicar y comprobar</b>.','Si sale rojo, no publiques: copia el mensaje y pide a la IA el archivo completo corregido.','Si sale verde, pulsa <b>Descargar archivo comprobado</b>.','Sustituye ese archivo en el repositorio.','GitHub Desktop: Commit to main → Push origin.','Abre la app en ventana privada y prueba el cambio.'])+[P('La caja comprueba sintaxis de JS, JSON, CSS y HTML, pero no sustituye una prueba real en móvil.','Note'),PageBreak()]
story += new('16. Mantener Gemini y Claude al día')+steps(['Después de cada versión, abre el Gem.','Elimina o sustituye los cuatro archivos de conocimiento antiguos.','Sube los cuatro `.md` nuevos del repositorio.','Sustituye las instrucciones pegadas si cambió el TXT.','Repite lo mismo en el proyecto de Claude.','Empieza chats nuevos; no continúes uno antiguo para una versión nueva.'])+[P('Archivos que se actualizan: AGENTS.md, CONTEXTO_ESTADISTICAS.md, MAPA_DEL_CODIGO.md, PROMPT_MAPA_TIRO.md y los dos TXT de instrucciones.','Note'),PageBreak()]
story += new('17. Pruebas antes de dar una versión por buena')+steps(['En la carpeta del repositorio abre Terminal o PowerShell.','Ejecuta <b>python tools/validate.py</b>. Debe terminar en TODO OK.','Ejecuta <b>python tests/smoke.py</b>. Debe terminar en TODO OK.','Ejecuta <b>python tools/capture.py capturas</b>.','Mira las capturas de PC y móvil, claro y oscuro.','Prueba manualmente importar un acta, abrir ambos equipos, ordenar MIN y navegar Jugadora → Partido.'])+[P('Si Playwright no está instalado: <b>pip install playwright</b> y después <b>python -m playwright install chromium</b>.','Note'),PageBreak()]
story += new('18. Si algo falla')+[table([['Problema','Qué comprobar'],['No importa Excel','Es .xlsx original y assets/jszip.min.js sigue en el repositorio.'],['No sincroniza','URL Worker, token, /health y binding DB.'],['Se queda v2','Recarga navegador; comprueba sw.js y caché estadisticas-v3.'],['Franja blanca','Abre la app instalada después de actualizar; theme-color debe cambiar.'],['Directo no baja','Solo debe bloquearse cuando ya hay partido activo.'],['Tabla no se mueve','Arrastra dentro de la tabla, no sobre el fondo del modal.'],['Mapa bloquea scroll','En lectura, touch-action debe ser pan-y.'],['IA omite código','Pide archivo completo en chat nuevo y vuelve a comprobar.']], [48*mm,122*mm])]+[PageBreak()]
story += new('19. Lista final')+bullets(['La app muestra v3 y conserva datos de v2.','Los tres partidos reales aparecen y cada acta tiene los dos equipos.','Las dos filas X · NOMBRE siguen separadas.','La tabla se desplaza y ordena por cualquier cabecera.','Directo configura con scroll y en curso cabe en 360×640.','Claro y oscuro cubren las áreas superior e inferior.','La pista SVG y las cuatro zonas coinciden con las coordenadas.','Jugadora abre sus partidos.','Gem y Claude tienen instrucciones y cuatro archivos de conocimiento.','actualizar.html crea un archivo enfocado, valida y descarga.','validate.py y smoke.py terminan en TODO OK.'])+[Spacer(1,7*mm),P('Guarda el ZIP original y una copia de seguridad JSON antes de cada cambio importante.','Note'),P('Fin de la guía','Smallx')]
doc.build(story,onFirstPage=footer,onLaterPages=footer);print(OUT)
